import{_ as p,a0 as r,w as o,s as d,ao as l,I as a,x as n,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux 系统开机启动项清理 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系统开机启动项清理 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系统开机启动项清理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系统开机启动项清理 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20160518 Cleaning Up Your Linux Startup Process","title":"Linux 系统开机启动项清理","tag":"201709","desc":""},"relativePath":"201709/20160518 Cleaning Up Your Linux Startup Process.md","filePath":"[post].md"}'),u={name:"201709/20160518 Cleaning Up Your Linux Startup Process.md"};function c(g,s,h,b,m,k){const e=r("Link");return o(),d("div",null,[s[17]||(s[17]=l(`<h1 id="linux-系统开机启动项清理" tabindex="-1">Linux 系统开机启动项清理 <a class="header-anchor" href="#linux-系统开机启动项清理" aria-label="Permalink to “Linux 系统开机启动项清理”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner-cleanup-startup.png?itok=dCcKwdoP" alt="Linux cleanup" title="Clean up your startup process"></p><p>一般情况下，常规用途的 Linux 发行版在开机启动时拉起各种相关服务进程，包括许多你可能无需使用的服务，例如<ruby>蓝牙<rt>bluetooth</rt></ruby>、Avahi、 <ruby>调制解调管理器<rt>ModemManager</rt></ruby>、ppp-dns（LCTT 译注：此处作者笔误 ppp-dns 应该为 pppd-dns) 等服务进程，这些都是什么东西？用于哪里，有何功能？</p><p>Systemd 提供了许多很好的工具用于查看系统启动情况，也可以控制在系统启动时运行什么。在这篇文章中，我将说明在 Systemd 类发行版中如何关闭一些令人讨厌的进程。</p><h3 id="查看开机启动项" tabindex="-1">查看开机启动项 <a class="header-anchor" href="#查看开机启动项" aria-label="Permalink to “查看开机启动项”">​</a></h3><p>在过去，你能很容易通过查看 <code>/etc/init.d</code> 了解到哪些服务进程会在引导时启动。Systemd 以不同的方式展现，你可以使用如下命令罗列允许开机启动的服务进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl list-unit-files --type=service | grep enabled</span></span>
<span class="line"><span>accounts-daemon.service                    enabled</span></span>
<span class="line"><span>anacron-resume.service                     enabled</span></span>
<span class="line"><span>anacron.service                            enabled</span></span>
<span class="line"><span>bluetooth.service                          enabled</span></span>
<span class="line"><span>brltty.service                             enabled</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>在此列表顶部，对我来说，蓝牙服务是冗余项，因为在该电脑上我不需要使用蓝牙功能，故无需运行此服务。下面的命令将停止该服务进程，并且使其开机不启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl stop bluetooth.service</span></span>
<span class="line"><span>$ sudo systemctl disable bluetooth.service</span></span></code></pre></div><p>你可以通过下面命令确定是否操作成功。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl status bluetooth.service</span></span>
<span class="line"><span> bluetooth.service - Bluetooth service</span></span>
<span class="line"><span>  Loaded: loaded (/lib/systemd/system/bluetooth.service; disabled; vendor preset: enabled)</span></span>
<span class="line"><span>  Active: inactive (dead)</span></span>
<span class="line"><span>    Docs: man:bluetoothd(8)</span></span></code></pre></div><p>停用的服务进程仍然能够被另外一个服务进程启动。如果你真的想在任何情况下系统启动时都不启动该进程，无需卸载该它，只需要把它掩盖起来就可以阻止该进程在任何情况下开机启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl mask bluetooth.service</span></span>
<span class="line"><span> Created symlink from /etc/systemd/system/bluetooth.service to /dev/null.</span></span></code></pre></div><p>一旦你对禁用该进程启动而没有出现负面作用感到满意，你也可以选择卸载该程序。</p><p>通过执行命令可以获得如下服务列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl list-unit-files --type=service                       </span></span>
<span class="line"><span>UNIT FILE                                  STATE   </span></span>
<span class="line"><span>accounts-daemon.service                    enabled</span></span>
<span class="line"><span>acpid.service                              disabled</span></span>
<span class="line"><span>alsa-restore.service                       static    </span></span>
<span class="line"><span>alsa-utils.service                         masked</span></span></code></pre></div><p>你不能启用或禁用静态服务，因为静态服务被其他的进程所依赖，并不意味着它们自己运行。</p><h3 id="哪些服务能够禁止" tabindex="-1">哪些服务能够禁止？ <a class="header-anchor" href="#哪些服务能够禁止" aria-label="Permalink to “哪些服务能够禁止？”">​</a></h3><p>如何知道你需要哪些服务，而哪些又是可以安全地禁用的呢？它总是依赖于你的个性化需求。</p><p>这里举例了几个服务进程的作用。许多服务进程都是发行版特定的，所以你应该看看你的发行版文档（比如通过 google 或 StackOverflow）。</p>`,20)),a("ul",null,[s[4]||(s[4]=l("<li><strong>accounts-daemon.service</strong> 是一个潜在的安全风险。它是 AccountsService 的一部分，AccountsService 允许程序获得或操作用户账户信息。我不认为有好的理由能使我允许这样的后台操作，所以我选择<ruby>掩盖<rt>mask</rt></ruby>该服务进程。</li><li><strong>avahi-daemon.service</strong> 用于零配置网络发现，使电脑超容易发现网络中打印机或其他的主机，我总是禁用它，别漏掉它。</li><li><strong>brltty.service</strong> 提供布莱叶盲文设备支持，例如布莱叶盲文显示器。</li><li><strong>debug-shell.service</strong> 开放了一个巨大的安全漏洞（该服务提供了一个无密码的 root shell ，用于帮助 调试 systemd 问题），除非你正在使用该服务，否则永远不要启动服务。</li><li><strong>ModemManager.service</strong> 该服务是一个被 dbus 激活的守护进程，用于提供移动<ruby>宽频<rt>broadband</rt></ruby>（2G/3G/4G）接口，如果你没有该接口，无论是内置接口，还是通过如蓝牙配对的电话，以及 USB 适配器，那么你也无需该服务。</li><li><strong>pppd-dns.service</strong> 是一个计算机发展的遗物，如果你使用拨号接入互联网的话，保留它，否则你不需要它。</li><li><strong>rtkit-daemon.service</strong> 听起来很可怕，听起来像是 rootkit。 但是你需要该服务，因为它是一个<ruby>实时内核调度器<rt>real-time kernel scheduler</rt></ruby>。</li>",7)),a("li",null,[s[1]||(s[1]=a("strong",null,"whoopsie.service",-1)),s[2]||(s[2]=n(" 是 Ubuntu 错误报告服务。它用于收集 Ubuntu 系统崩溃报告，并发送报告到 ",-1)),i(e,{href:"https://daisy.ubuntu.com"},{default:t(()=>[...s[0]||(s[0]=[n("https://daisy.ubuntu.com",-1)])]),_:1}),s[3]||(s[3]=n(" 。 你可以放心地禁止其启动，或者永久的卸载它。",-1))]),s[5]||(s[5]=a("li",null,[a("strong",null,"wpa_supplicant.service"),n(" 仅在你使用 Wi-Fi 连接时需要。")],-1))]),s[18]||(s[18]=l(`<h3 id="系统启动时发生了什么" tabindex="-1">系统启动时发生了什么？ <a class="header-anchor" href="#系统启动时发生了什么" aria-label="Permalink to “系统启动时发生了什么？”">​</a></h3><p>Systemd 提供了一些命令帮助调试系统开机启动问题。该命令会重演你的系统启动的所有消息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl -b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- Logs begin at Mon 2016-05-09 06:18:11 PDT,</span></span>
<span class="line"><span>end at Mon 2016-05-09 10:17:01 PDT. --</span></span>
<span class="line"><span>May 16 06:18:11 studio systemd-journal[289]:</span></span>
<span class="line"><span>Runtime journal (/run/log/journal/) is currently using 8.0M.</span></span>
<span class="line"><span>Maximum allowed usage is set to 157.2M.</span></span>
<span class="line"><span>Leaving at least 235.9M free (of currently available 1.5G of space).</span></span>
<span class="line"><span>Enforced usage limit is thus 157.2M.</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>通过命令 <code>journalctl -b -1</code> 可以复审前一次启动，<code>journalctl -b -2</code> 可以复审倒数第 2 次启动，以此类推。</p><p>该命令会打印出大量的信息，你可能并不关注所有信息，只是关注其中问题相关部分。为此，系统提供了几个过滤器，用于帮助你锁定目标。让我们以进程号为 1 的进程为例，该进程是所有其它进程的父进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl _PID=1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Starting LSB: Raise network interfaces....</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Started LSB: Raise network interfaces..</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Reached target System Initialization.</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Started CUPS Scheduler.</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Listening on D-Bus System Message Bus Socket</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Listening on CUPS Scheduler.</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>这些打印消息显示了什么被启动，或者是正在尝试启动。</p><p>一个最有用的命令工具之一 <code>systemd-analyze blame</code>，用于帮助查看哪个服务进程启动耗时最长。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemd-analyze blame</span></span>
<span class="line"><span>         8.708s gpu-manager.service</span></span>
<span class="line"><span>         8.002s NetworkManager-wait-online.service</span></span>
<span class="line"><span>         5.791s mysql.service</span></span>
<span class="line"><span>         2.975s dev-sda3.device</span></span>
<span class="line"><span>         1.810s alsa-restore.service</span></span>
<span class="line"><span>         1.806s systemd-logind.service</span></span>
<span class="line"><span>         1.803s irqbalance.service</span></span>
<span class="line"><span>         1.800s lm-sensors.service</span></span>
<span class="line"><span>         1.800s grub-common.service</span></span></code></pre></div><p>这个特定的例子没有出现任何异常，但是如果存在系统启动瓶颈，则该命令将能发现它。</p><p>你也能通过如下资源了解 Systemd 如何工作：</p>`,11)),a("ul",null,[a("li",null,[i(e,{href:"https://www.linux.com/learn/understanding-and-using-systemd"},{default:t(()=>[...s[6]||(s[6]=[n("理解和使用 Systemd",-1)])]),_:1})]),a("li",null,[i(e,{href:"https://www.linux.com/learn/intro-systemd-runlevels-and-service-management-commands"},{default:t(()=>[...s[7]||(s[7]=[n("介绍 Systemd 运行级别和服务管理命令",-1)])]),_:1})]),a("li",null,[i(e,{href:"https://www.linux.com/learn/here-we-go-again-another-linux-init-intro-systemd"},{default:t(()=>[...s[8]||(s[8]=[n("再次前行，另一个 Linux 初始化系统：Systemd 介绍",-1)])]),_:1})])]),s[19]||(s[19]=a("hr",null,null,-1)),a("p",null,[s[10]||(s[10]=n("via: ",-1)),i(e,{href:"https://www.linux.com/learn/cleaning-your-linux-startup-process"},{default:t(()=>[...s[9]||(s[9]=[n("https://www.linux.com/learn/cleaning-your-linux-startup-process",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=n("作者：",-1)),i(e,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[11]||(s[11]=[n("David Both",-1)])]),_:1}),s[15]||(s[15]=n(" 译者：",-1)),i(e,{href:"https://github.com/penghuster"},{default:t(()=>[...s[12]||(s[12]=[n("penghuster",-1)])]),_:1}),s[16]||(s[16]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[n("wxy",-1)])]),_:1})]),s[20]||(s[20]=a("p",null,"本文由 LCTT 原创编译，Linux中国 荣誉推出",-1))])}const x=p(u,[["render",c]]);export{f as __pageData,x as default};
